import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Competitive Intelligence — Troubleshooting & FAQs","description":"","frontmatter":{},"headers":[],"relativePath":"competitive-intel-04-troubleshooting-and-faqs.md","filePath":"competitive-intel-04-troubleshooting-and-faqs.md"}'),n={name:"competitive-intel-04-troubleshooting-and-faqs.md"};function i(s,e,l,p,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="competitive-intelligence-—-troubleshooting-faqs" tabindex="-1">Competitive Intelligence — Troubleshooting &amp; FAQs <a class="header-anchor" href="#competitive-intelligence-—-troubleshooting-faqs" aria-label="Permalink to &quot;Competitive Intelligence — Troubleshooting &amp; FAQs&quot;">​</a></h1><p><em>Common issues, edge cases, and answers to frequent questions</em></p><hr><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><h3 id="who-can-use-competitive-intelligence" tabindex="-1">Who can use Competitive Intelligence? <a class="header-anchor" href="#who-can-use-competitive-intelligence" aria-label="Permalink to &quot;Who can use Competitive Intelligence?&quot;">​</a></h3><p>Any workspace member can view reports, add and remove competitors, generate reports on demand, and configure settings. There are no admin-only restrictions in this module.</p><h3 id="how-long-does-report-generation-take" tabindex="-1">How long does report generation take? <a class="header-anchor" href="#how-long-does-report-generation-take" aria-label="Permalink to &quot;How long does report generation take?&quot;">​</a></h3><p>Typically a few minutes. A loading indicator is shown while a report is generating. You can navigate away and return — the report status will update to Completed when it is ready.</p><h3 id="can-i-generate-more-than-one-report-at-a-time" tabindex="-1">Can I generate more than one report at a time? <a class="header-anchor" href="#can-i-generate-more-than-one-report-at-a-time" aria-label="Permalink to &quot;Can I generate more than one report at a time?&quot;">​</a></h3><p>You can trigger a new generation at any time, but multiple simultaneous generations are not recommended — wait for one to complete before generating another.</p><h3 id="does-removing-a-competitor-affect-previous-reports" tabindex="-1">Does removing a competitor affect previous reports? <a class="header-anchor" href="#does-removing-a-competitor-affect-previous-reports" aria-label="Permalink to &quot;Does removing a competitor affect previous reports?&quot;">​</a></h3><p>No. Removing a competitor removes them from future report generation but does not alter any existing reports. All previously generated reports remain accessible exactly as they were.</p><h3 id="can-i-edit-the-content-of-a-generated-report" tabindex="-1">Can I edit the content of a generated report? <a class="header-anchor" href="#can-i-edit-the-content-of-a-generated-report" aria-label="Permalink to &quot;Can I edit the content of a generated report?&quot;">​</a></h3><p>No. Report content is read-only. If a report doesn&#39;t reflect what you were looking for, improve the industry description and generate a fresh report.</p><h3 id="what-happens-when-i-click-extract-features-from-report" tabindex="-1">What happens when I click &quot;Extract Features from Report&quot;? <a class="header-anchor" href="#what-happens-when-i-click-extract-features-from-report" aria-label="Permalink to &quot;What happens when I click &quot;Extract Features from Report&quot;?&quot;">​</a></h3><p>You are redirected to the Extracts module. The report content is analyzed by AI, and any feature ideas, problems, or opportunities found in the analysis appear as extract cards in your review queue. These extracts carry an <strong>Intel Report</strong> source badge. From there you review and decide which ideas to add to your backlog.</p><h3 id="can-i-schedule-reports-less-frequently-than-biweekly" tabindex="-1">Can I schedule reports less frequently than biweekly? <a class="header-anchor" href="#can-i-schedule-reports-less-frequently-than-biweekly" aria-label="Permalink to &quot;Can I schedule reports less frequently than biweekly?&quot;">​</a></h3><p>Not currently. The available scheduling options are Weekly and Biweekly. For less frequent monitoring, you can turn off automatic scheduling and generate reports manually as needed.</p><h3 id="is-the-industry-description-the-same-as-the-organization-description-in-settings" tabindex="-1">Is the industry description the same as the Organization Description in Settings? <a class="header-anchor" href="#is-the-industry-description-the-same-as-the-organization-description-in-settings" aria-label="Permalink to &quot;Is the industry description the same as the Organization Description in Settings?&quot;">​</a></h3><p>No. These are separate inputs. The Organization Description (in Settings &gt; Organization) is used by the Documents module for AI-generated artifacts like PRDs and Opportunity Canvases. The Industry Description in Competitive Intelligence is used only for competitor analysis reports.</p><h3 id="can-reports-be-shared-with-people-outside-lodestone" tabindex="-1">Can reports be shared with people outside Lodestone? <a class="header-anchor" href="#can-reports-be-shared-with-people-outside-lodestone" aria-label="Permalink to &quot;Can reports be shared with people outside Lodestone?&quot;">​</a></h3><p>Reports can be downloaded as PDFs, which can then be shared by any means (email, Slack, etc.). There is no shareable link or in-app sharing option.</p><hr><h2 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h2><h3 id="the-generate-report-button-is-disabled" tabindex="-1">The Generate Report button is disabled <a class="header-anchor" href="#the-generate-report-button-is-disabled" aria-label="Permalink to &quot;The Generate Report button is disabled&quot;">​</a></h3><p>This means your competitor list is empty. Add at least one competitor before attempting to generate a report.</p><h3 id="a-report-shows-failed-status" tabindex="-1">A report shows &quot;Failed&quot; status <a class="header-anchor" href="#a-report-shows-failed-status" aria-label="Permalink to &quot;A report shows &quot;Failed&quot; status&quot;">​</a></h3><p>Generation failure can happen if the AI encountered an error during analysis. Click into the failed report to see any error details. The recommended resolution is to go back to the reports list and generate a new report. If the issue persists, check that your industry description is filled in and that your competitor list is not empty.</p><h3 id="ai-competitor-suggestions-feel-irrelevant" tabindex="-1">AI competitor suggestions feel irrelevant <a class="header-anchor" href="#ai-competitor-suggestions-feel-irrelevant" aria-label="Permalink to &quot;AI competitor suggestions feel irrelevant&quot;">​</a></h3><p>This is almost always caused by a vague or generic industry description. Update your industry description in the Competitive Intelligence settings to be more specific about your market category, customer type, and competitive context. Run the suggestion feature again after saving the updated description.</p><h3 id="no-features-are-appearing-after-extract-features-from-report" tabindex="-1">No features are appearing after &quot;Extract Features from Report&quot; <a class="header-anchor" href="#no-features-are-appearing-after-extract-features-from-report" aria-label="Permalink to &quot;No features are appearing after &quot;Extract Features from Report&quot;&quot;">​</a></h3><p>A few things to check:</p><ul><li>Confirm the report has a <strong>Completed</strong> status before extracting — only completed reports can be analyzed</li><li>If extraction ran but produced no extracts, the report content may not contain enough clear product signals. This can happen with reports covering markets with limited public competitor activity.</li><li>If you were redirected to Extracts but the queue appears empty, allow a moment for AI processing to complete and refresh the page</li></ul><h3 id="automatic-reports-aren-t-being-generated" tabindex="-1">Automatic reports aren&#39;t being generated <a class="header-anchor" href="#automatic-reports-aren-t-being-generated" aria-label="Permalink to &quot;Automatic reports aren&#39;t being generated&quot;">​</a></h3><p>Check that:</p><ul><li>A report schedule has been configured in the Competitive Intelligence settings (frequency and day are set)</li><li>Your competitor list is not empty</li><li>The report day you selected has actually passed since the schedule was set — if you set a Wednesday schedule on a Thursday, the first automatic report won&#39;t generate until next Wednesday</li></ul><hr><p><em>This is version 1 of the Competitive Intelligence documentation, documenting confirmed platform behavior.</em></p>',38)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
